body:
گاهی می‌خواهیم متن ما برجسته شود. برای این کار می‌توانیم آن را /مورب/، *پررنگ* و چیزهای دیگر کنیم!

برای مثال، برای مورب کردن متن، آن را بین دو خط اریب //بگذار//، مثل //سلام//. برای مثال:

\Group(
	Stack()
	[
		Phrase(`می‌خواهی در متن خود /مورب/ را نشان بدهی؟`)
		Phrase(
			`این کار برای تأکید یا برای دادن آن /جلوهٔ ویژه/ به کلمات تو خوب است.`
		)
		Phrase(
			`فقط یک خط اریب (//) پیش و پس از کلمه یا عبارت بگذار، /مثل این/ به کلمات تو خوب است.`
		)
	]
)\

@Phrase  می‌تواند متن را پررنگ هم بکند. برای این کار متن خود را بین دو ستاره **بگذار**، مثل **سلام**. برای مثال:

\Group(
	Stack()
	[
		Phrase(`می‌خواهی متن خود را با *پررنگ* برجسته کنی؟`)
		Phrase(
			`این کار وقتی خوب است که بخواهی *چیزی را با صدای بلند بگویی* به کلمات تو خوب است.`
		)
		Phrase(
			`فقط دور کلماتت یک ستاره (**) بگذار، مثل *سلام!*، و ببین چطور فرق می‌کند.`
		)
	]
)\

@Phrase  می‌تواند متن را خیلی پررنگ هم بکند. برای این کار، متن خود را بین دو علامت ^^بگذار^^، مثل ^^سلام^^. برای مثال:

\Group(
	Stack()
	[
		Phrase(
			`وقتی می‌خواهی حس نوشته را به اوج برسانی، فوق‌ضخیم بهترین گزینه است.^بهترین^ وقتی می‌خواهی حس نوشته را به اوج برسانی.`
		)
		Phrase(
			`مثل ضخیم است ولی خیلی ^داغ‌تر^، و معمولاً با دو علامت ^^ در دو طرف نوشته می‌شود.`
		)
		Phrase(
			`از آن برای برجسته کردن ^عنوان‌ها^ یا ^ایده‌های بزرگ^ به کلمات تو خوب است.`
		)
	]
)\

در پایان،  @Phrase  می‌تواند زیر نوشته خط بکشد. برای این کار، نوشته را میان دو خط زیرین __ بگذار، مثل __سلام__. برای نمونه:

\Group(
	Stack()
	[
		Phrase(
			`زیرخط _آرام ولی جذاب است_ برای وقتی که می‌خواهی نوشته ساده بماند ولی همچنان دیده شود.`
		)
		Phrase(
			`یک خط زیرین (__) پیش و پس از نوشته بگذار، _مثل این_، تا تأکیدی ساده و تمیز به آن بدهی.`
		)
		Phrase(
			`این کار _عالی_ است برای رساندن حرفت بدون اینکه خیلی _پرزرق‌وبرق_ به کلمات تو خوب است.`
		)
	]
)\

گاهی می‌خواهیم داستان بگوییم، شعر نشان دهیم، یا شعری را متحرک کنیم.برای این کار می‌توانیم از  @Scene  و  @Phrase  با هم استفاده کنیم تا یک توالی را نشان دهیم.

برای نمونه، فرض کنیم می‌خواهیم شعر کوتاه کودکانهٔ «جک چابک باش» را متحرک کنیم.می‌توانیم یک  @Scene  بسازیم که هر خط آن یک  @Phrase  باشد، و با تنظیم  @Phrase/duration  هر خط،  @Scene  وقتی هر عبارت تمام شود، جلو می‌رود.

\Scene(
	[
		Phrase('جک چابک باش' مدت: 1s)
		Phrase('جک تند باش' مدت: 1s)
		Phrase('جک از روی شمع بپر' مدت: 1s)
	]
)\

@Scene  همچنین منتظر می‌ماند تا  @Sequence  هم تمام شود. بیایید خط شمع را بپرانیم!

\Scene(
	[
		Phrase('جک چابک باش' مدت: 1s)
		Phrase('جک تند باش' مدت: 1s)
		Phrase(
			'جک از روی شمع بپر'
			درحالورود: Sequence.bounce(مدت: 1s)
		)
	]
)\

@Scene  همچنین می‌تواند یک  @Group  از متن هم بگیرد، و منتظر می‌ماند تا تمام محتوای آن حرکت خود را تمام کند.

\Scene(
	[
		Group(
			Stack()
			[Phrase('جک چابک باش') Phrase('جک تند باش')]
			مدت: 2s
		)
		Phrase(
			'جک از روی شمع بپر'
			درحالورود: Sequence.bounce(مدت: 1s)
		)
	]
)\

گاهی می‌خواهیم یک کاراکتر چند بار به یک شکل حرکت کند! نوشتن همان خط‌ها بارها و بارها خسته‌کننده می‌شود.

در عوض، می‌توانیم از  @Sequence  همراه با  @Phrase  استفاده کنیم تا چیزی چند بار تکرار شود! به‌طور دقیق‌تر،می‌توانیم از شمارش در  @Sequence  استفاده کنیم و انتخاب کنیم که یک گروه از حالت‌ها چند بار اتفاق بیفتد. برای نمونه، این هم یک توپ بسکتبال که دو بار بالا و پایین می‌پرد. 

\Stage(
	[
		Phrase(
			'🏀'
			درحالورود: Sequence(
				{
					0%: Pose(فاصله: Place(y: 0.25m))
					25%: Pose(فاصله: Place(y: 0m))
					50%: Pose(فاصله: Place(y: -0.25m))
					75%: Pose(فاصله: Place(y: 0m))
					100%: Pose(فاصله: Place(y: 0.25m))
				}
				شمار: 2x
				مدت: 2s
			)
		)
	]
)\
